        (d_dir / "risk_free_rate.json").write_text(json.dumps(risk_free_payload, indent=2), encoding="utf-8")
        (d_dir / "dividend_yields.json").write_text(json.dumps(dividend_payload, indent=2), encoding="utf-8")

        # Write real 2026-11-09 .json.gz archive into data/google_archive/
